ALTER TABLE plan_prices MODIFY COLUMN interval_code ENUM('day','two_weeks','month','thirty_days') NOT NULL;
ALTER TABLE plan_versions MODIFY COLUMN approved_by BIGINT UNSIGNED NULL,
 ADD COLUMN approval_kind ENUM('operator','documented_product') NOT NULL DEFAULT 'operator',
 ADD CONSTRAINT chk_plan_approval_actor CHECK ((approval_kind='operator' AND approved_by IS NOT NULL) OR
 (approval_kind='documented_product' AND approval_reference='user-approved:simora-access-v1:2026-11-06'));
ALTER TABLE subscriptions ADD UNIQUE KEY uq_subscription_policy (id,plan_version_id);
ALTER TABLE entitlements MODIFY COLUMN approved_by BIGINT UNSIGNED NULL,
 ADD COLUMN approval_kind ENUM('operator','documented_product') NOT NULL DEFAULT 'operator',
 ADD COLUMN plan_version_id BIGINT UNSIGNED NULL,
 ADD CONSTRAINT fk_entitlement_policy_subscription FOREIGN KEY (subscription_id,plan_version_id) REFERENCES subscriptions(id,plan_version_id),
 ADD CONSTRAINT chk_entitlement_approval_actor CHECK ((approval_kind='operator' AND approved_by IS NOT NULL) OR
 (approval_kind='documented_product' AND plan_version_id IS NOT NULL AND subscription_id IS NOT NULL AND
 approval_reference='user-approved:simora-access-v1:2026-11-06'));
ALTER TABLE usage_events ADD COLUMN entitlement_id BIGINT UNSIGNED NULL,
 ADD CONSTRAINT fk_usage_event_entitlement_owner FOREIGN KEY (user_id,entitlement_id) REFERENCES entitlements(user_id,id);
INSERT INTO plan_versions (plan_id,version,features,approval_reference,approved_by,approval_kind,approved_at,effective_at) SELECT p.id,(SELECT COALESCE(MAX(v.version),0)+1 FROM plan_versions v WHERE v.plan_id=p.id),'{"schema_version":"simora.access.v1","code":"trial","amount_minor":200000,"currency":"NGN","validity_seconds":86400,"models":["spe"],"markets":["over_15","under_35"],"analyses_limit":null,"simulator_runs_limit":null,"history_days":3,"simulation_outcomes":50,"saved_strategies_limit":0,"csv_exports_per_day":0,"comparison_tier":"none","comparison_history_days":null,"comparison_metrics":[],"comparison_agreement":false,"comparison_custom_dates":false,"comparison_export":false,"advanced_analytics":false,"automation_configuration_limit":0,"future_trading_sessions_limit":0,"execution_enabled":false,"daily_reset_timezone":"Africa/Lagos","rollover":false,"trial_once_verified":true}','user-approved:simora-access-v1:2026-11-06',NULL,'documented_product',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM plans p WHERE p.code='trial';
